<?= $this->extend(ADMIN_VIEW.'layout') ?><?= $this->section('main-content') ?>
<?php if (!empty($lead['images'])): ?><section class="dashboard-container pt-0"><div class="card shadow-sm mb-4"><div class="card-header"><h2 class="h5 mb-0">Uploaded skin images</h2></div><div class="card-body"><div class="row"><?php foreach ($lead['images'] as $image): ?><div class="col-sm-6 col-lg-3 mb-3"><div class="border rounded p-2 h-100"><div class="small text-muted mb-2"><?= esc(ucfirst((string) $image['angle'])) ?></div><?php if (!empty($image['temporary_url'])): ?><img src="<?= esc($image['temporary_url']) ?>" alt="Skin image" class="img-fluid rounded" style="height:180px;width:100%;object-fit:cover"><?php else: ?><div class="alert alert-warning mb-0">Preview unavailable</div><?php endif; ?></div></div><?php endforeach; ?></div></div></div></section><?php endif; ?>
<main class="dashboard-container"><div class="page-heading"><div><div class="page-eyebrow">Shopify / AI Skin Analysis lead</div><h1 class="h3 mb-1"><?= esc($lead['lead_reference']) ?></h1><p class="text-muted mb-0"><?= esc($lead['first_name']) ?> · <?= esc($lead['store_domain']) ?></p></div><a class="btn btn-outline-primary" href="<?= base_url('admin/integrations/shopify/ai-skin-analysis/leads') ?>">Back to leads</a></div><section class="card shadow-sm mb-4"><div class="card-body"><strong>Status:</strong> <?= esc(ucwords(str_replace('_',' ',$lead['status']))) ?><?php if(!empty($lead['patient_reference'])): ?><div class="alert alert-success mt-3 mb-0">Patient: <?= esc($lead['patient_reference']) ?></div><?php else: ?><form id="skin-patient-link" class="form-inline mt-3"><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><input class="form-control mr-2" name="patient_reference" placeholder="PAT-000001" required><button class="btn btn-outline-primary">Link existing patient</button></form><form id="skin-patient-create" class="form-inline mt-3"><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><input class="form-control mr-2" name="country_code" value="<?= esc((string)($lead['country_code']??'')) ?>" placeholder="+91" required><input class="form-control mr-2" name="mobile_number" value="<?= esc((string)($lead['mobile_number']??'')) ?>" placeholder="Mobile" required><input class="form-control mr-2" name="date_of_birth" value="<?= esc((string)($lead['date_of_birth']??'')) ?>" type="date" required><button class="btn btn-primary">Create global patient</button></form><?php endif; ?></div></section><?php if($lead['status']==='completed'): ?><section class="card shadow-sm"><div class="card-header">AI skin report</div><div class="card-body"><pre style="white-space:pre-wrap;word-break:break-word"><?= esc(json_encode(json_decode((string)$lead['result_json'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)) ?></pre></div></section><?php elseif($lead['status']==='failed'): ?><div class="alert alert-danger d-flex justify-content-between align-items-center"><span>Analysis failed: <?= esc((string)($lead['error_code']??'Unknown error')) ?></span><button type="button" class="btn btn-sm btn-outline-danger" id="skin-analysis-retry">Retry analysis</button></div><?php endif; ?></main><?= $this->endSection() ?><?= $this->section('scripts') ?><script>$(function(){$('#skin-patient-link,#skin-patient-create').on('submit',function(e){e.preventDefault();var f=$(this),b=f.find('button');b.prop('disabled',true);$.ajax({url:f.attr('id')==='skin-patient-create'?'<?= base_url('admin/integrations/shopify/ai-skin-analysis/leads/'.(int)$lead['id'].'/create-patient') ?>':'<?= base_url('admin/integrations/shopify/ai-skin-analysis/leads/'.(int)$lead['id'].'/link-patient') ?>',method:'POST',data:f.serialize(),headers:{'X-Requested-With':'XMLHttpRequest'},success:function(r){if(r.status)location.reload();else alert(r.msg||'Operation failed.');},error:function(x){alert((x.responseJSON||{}).msg||'Operation failed safely.');},complete:function(){b.prop('disabled',false);}});});$('#skin-analysis-retry').on('click',function(){var b=$(this);b.prop('disabled',true).text('Retrying…');$.ajax({url:'<?= base_url('admin/integrations/shopify/ai-skin-analysis/leads/'.(int)$lead['id'].'/retry') ?>',method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},data:{'<?= csrf_token() ?>':'<?= csrf_hash() ?>'},success:function(r){if(r.status)location.reload();else alert(r.msg||'Retry failed.');},error:function(x){alert((x.responseJSON||{}).msg||'Retry failed safely.');},complete:function(){b.prop('disabled',false).text('Retry analysis');}});});});</script><?= $this->endSection() ?>
